export function meanReturn(returns: number[]): number {
  const sum = returns.reduce((s, r) => s + r, 0);
  return sum / returns.length;
}

export function stdDev(returns: number[]): number {
  const m = meanReturn(returns);
  const variance = returns.reduce((s, r) => s + (r - m) ** 2, 0) / returns.length;
  return Math.sqrt(variance);
}
